private async Task RefreshData()
{
    categories = (await CategoryRepository.GetAllAsync()).ToList();
    entries = (await EntryRepository.GetAllAsync()).ToList();
    await BackupDatabase();  // called on EVERY page load + every add/delete/clear
}

private async Task BackupDatabase()
{
    var data = await ContestManager.ExportDataAsync();  // full DB read
    if (data.Length > 0)
    {
        await LocalStorage.SetItemAsStringAsync("db_backup", Convert.ToBase64String(data));
    }
}

